    28	  for (let i = 0; i < 256; i += 1) {
    29	    const b = ginv(i);
    30	    let s = b;
    31	    let r = b;
    32	    for (let k = 0; k < 4; k += 1) {
    33	      r = rotl8(r);
    34	      s ^= r;
    35	    }
    36	    sbox[i] = (s ^ 0x63) & 0xff;
