     1	/**
     2	 * pyaes modes of operation. Only ECB is needed here, and only its
     3	 * single-block behaviour.
     4	 */
     5	
     6	import { ValueError } from '../python/exceptions.mjs';
     7	import { addOuterFrame, frame } from '../python/frames.mjs';
     8	import { AES } from './blockCipher.mjs';
     9	import { BLOCK_SIZE } from './keyExpansion.mjs';
    10	
    11	/** Line numbers pyaes reports in its tracebacks, as observed from the bundle. */
    12	const AES_INIT_LINE = 134;
    13	const ECB_INIT_LINE = 304;
    14	const ECB_ENCRYPT_LINE = 342;
    15	const ECB_DECRYPT_LINE = 349;
    16	const SOURCE = 'pyaes/aes.py';
    17	
    18	/**
    19	 * AES applied one block at a time with no chaining — Electronic Codebook.
    20	 *
    21	 * `encrypt` and `decrypt` each require exactly one 16-byte block; unlike the
    22	 * buffered `Encrypter`/`Decrypter` wrappers, this class does no padding.
    23	 */
    24	export class AESModeOfOperationECB {
    25	  /**
    26	   * @param {Uint8Array} key 16, 24 or 32 bytes
    27	   */
    28	  constructor(key) {
    29	    try {
    30	      this._aes = new AES(key);
    31	    } catch (error) {
    32	      if (error instanceof ValueError) {
    33	        addOuterFrame(error, frame(SOURCE, AES_INIT_LINE, '__init__'));
    34	        throw addOuterFrame(error, frame(SOURCE, ECB_INIT_LINE, '__init__'));
    35	      }
    36	      throw error;
    37	    }
    38	  }
    39	
    40	  /** @returns {string} */
    41	  get name() {
    42	    return 'Electronic Codebook (ECB)';
    43	  }
    44	
    45	  /**
    46	   * Encrypt one block.
    47	   *
    48	   * @param {Uint8Array} plaintext exactly 16 bytes
    49	   * @returns {Uint8Array} 16 bytes of ciphertext
    50	   */
    51	  encrypt(plaintext) {
    52	    if (plaintext.length !== BLOCK_SIZE) {
    53	      throw addOuterFrame(
    54	        new ValueError('plaintext block must be 16 bytes'),
    55	        frame(SOURCE, ECB_ENCRYPT_LINE, 'encrypt'),
    56	      );
    57	    }
    58	    return this._aes.encrypt(plaintext);
    59	  }
    60	
    61	  /**
    62	   * Decrypt one block.
    63	   *
    64	   * @param {Uint8Array} ciphertext exactly 16 bytes
    65	   * @returns {Uint8Array} 16 bytes of plaintext
    66	   */
    67	  decrypt(ciphertext) {
    68	    if (ciphertext.length !== BLOCK_SIZE) {
    69	      throw addOuterFrame(
    70	        new ValueError('ciphertext block must be 16 bytes'),
    71	        frame(SOURCE, ECB_DECRYPT_LINE, 'decrypt'),
    72	      );
    73	    }
    74	    return this._aes.decrypt(ciphertext);
    75	  }
    76	}

