     1	/**
     2	 * The two text codecs this program depends on.
     3	 *
     4	 * A Python `str` is modelled as a JavaScript string that may contain lone
     5	 * surrogates in U+DC80..U+DCFF — exactly what `errors='surrogateescape'`
     6	 * produces for bytes that are not valid UTF-8. JavaScript strings tolerate
     7	 * lone surrogates, so the model is faithful, including the fact that encoding
     8	 * such a string back to UTF-8 with strict errors fails.
     9	 */
    10	
    11	import { UnicodeEncodeError } from './exceptions.mjs';
    12	
    13	const SURROGATE_LOW = 0xd800;
    14	const SURROGATE_HIGH = 0xdfff;
    15	const SURROGATE_ESCAPE_BASE = 0xdc00;
    16	
    17	/**
    18	 * How many continuation bytes a lead byte announces, and the legal range of
    19	 * the first continuation. Returns null for bytes that cannot start a sequence.
    20	 *
    21	 * @param {number} lead
    22	 * @returns {{length: number, min: number, max: number} | null}
    23	 */
    24	function leadByteInfo(lead) {
    25	  if (lead < 0x80) return { length: 1, min: 0, max: 0 };
    26	  if (lead < 0xc2) return null; // continuation byte, or overlong C0/C1
    27	  if (lead < 0xe0) return { length: 2, min: 0x80, max: 0xbf };
    28	  if (lead === 0xe0) return { length: 3, min: 0xa0, max: 0xbf }; // no overlongs
    29	  if (lead === 0xed) return { length: 3, min: 0x80, max: 0x9f }; // no surrogates
    30	  if (lead < 0xf0) return { length: 3, min: 0x80, max: 0xbf };
    31	  if (lead === 0xf0) return { length: 4, min: 0x90, max: 0xbf }; // no overlongs
    32	  if (lead === 0xf4) return { length: 4, min: 0x80, max: 0x8f }; // <= U+10FFFF
    33	  if (lead < 0xf4) return { length: 4, min: 0x80, max: 0xbf };
    34	  return null; // 0xf5..0xff are always invalid
    35	}
    36	
    37	/**
    38	 * Decode bytes as UTF-8, mapping each undecodable byte to U+DC00 + byte the way
    39	 * CPython's `surrogateescape` handler does. This is how the interpreter turns
    40	 * `argv` into `str` objects.
    41	 *
    42	 * @param {Uint8Array} bytes
    43	 * @returns {string} a Python-`str`-shaped JavaScript string
    44	 */
    45	export function decodeSurrogateEscape(bytes) {
    46	  let out = '';
    47	  let i = 0;
    48	
    49	  /**
    50	   * Escape `count` bytes starting at `from` and advance past them.
    51	   *
    52	   * @param {number} from
    53	   * @param {number} count
    54	   */
    55	  const escapeRun = (from, count) => {
    56	    for (let k = 0; k < count; k += 1) {
    57	      out += String.fromCharCode(SURROGATE_ESCAPE_BASE + bytes[from + k]);
    58	    }
    59	  };
    60	
    61	  while (i < bytes.length) {
    62	    const lead = bytes[i];
    63	    if (lead < 0x80) {
    64	      out += String.fromCharCode(lead);
    65	      i += 1;
    66	      continue;
    67	    }
    68	
    69	    const info = leadByteInfo(lead);
    70	    if (info === null) {
    71	      escapeRun(i, 1);
    72	      i += 1;
    73	      continue;
    74	    }
    75	
    76	    // Count how much of the announced sequence is actually well formed.
    77	    let consumed = 1;
    78	    let valid = true;
    79	    for (let k = 1; k < info.length; k += 1) {
    80	      const byte = bytes[i + k];
    81	      const min = k === 1 ? info.min : 0x80;
    82	      const max = k === 1 ? info.max : 0xbf;
    83	      if (byte === undefined || byte < min || byte > max) {
