// independent S-box: table-free, computed by brute-force inverse + affine
function mul(a,b){let p=0;for(let i=0;i<8;i++){if(b&1)p^=a;const h=a&0x80;a=(a<<1)&0xff;if(h)a^=0x1b;b>>=1;}return p&0xff;}
for(let i=0;i<256;i++){
  let inv=0; if(i!==0){ for(let j=1;j<256;j++) if(mul(i,j)===1){inv=j;break;} }
  let s=0; for(let k=0;k<8;k++){ // s_k = b_k ^ b_{k+4} ^ b_{k+5} ^ b_{k+6} ^ b_{k+7} ^ c_k
    const bit=(n)=>(inv>>((n)%8))&1;
    const v = bit(k)^bit(k+4)^bit(k+5)^bit(k+6)^bit(k+7)^((0x63>>k)&1);
    s |= v<<k;
  }
  S[i]=s;
}
function refExpand(key){
  const nk=key.length/4, nr=nk+6, w=[];
  for(let i=0;i<nk;i++) w.push(((key[4*i]<<24)|(key[4*i+1]<<16)|(key[4*i+2]<<8)|key[4*i+3])>>>0);
  const sw=(x)=>((S[(x>>>24)&255]<<24)|(S[(x>>>16)&255]<<16)|(S[(x>>>8)&255]<<8)|S[x&255])>>>0;
  const rw=(x)=>(((x<<8)|(x>>>24))>>>0);
  for(let i=nk;i<4*(nr+1);i++){
    let t=w[i-1];
    if(i%nk===0) t=(sw(rw(t))^(RC[i/nk]<<24))>>>0;
    else if(nk===8 && i%nk===4) t=sw(t);
    w.push((w[i-nk]^t)>>>0);
  }
  return w;
}
let s0=1,s1=2,s2=3,s3=4;
function xr(){let t=s0;t^=t<<11;t^=t>>>8;s0=s1;s1=s2;s2=s3;s3^=s3>>>19;s3^=t;return s3>>>0;}
